DROP FUNCTION IF EXISTS nexus.text_gated_search_384(vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_768(vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_1024(vector, text, text[], jsonb, text, int);
